// Memory Auditor — analysis step (runs inside an n8n Code node, "Run Once for All Items").
// Input: the response of GET /api/v1/executions/{id}?includeData=true
//        or GET /api/v1/executions?workflowId=...&includeData=true&limit=1
// Output: one summary item, then one item per node sorted by data size (largest first).

const settings = $('Settings').first().json;
const res = $input.first().json;
const exec = Array.isArray(res.data) ? res.data[0] : res;

if (!exec) {
  throw new Error('No execution found. Run the workflow you want to measure once, then try again.');
}
const runData = exec.data && exec.data.resultData && exec.data.resultData.runData;
if (!runData) {
  throw new Error(
    `Execution ${exec.id} has no saved node data. Check that the workflow saves execution data ` +
      '(Workflow settings > Save execution progress / Save manual executions). A crashed (OOM) execution usually has no data; run it again with a smaller sample.'
  );
}

const MB = 1024 * 1024;
const UNITS = { b: 1, kb: 1024, mb: MB, gb: 1024 * MB };

// Binary metadata carries a human-readable fileSize such as "1.23 MB" or "456 kB".
function parseFileSize(text) {
  const m = /([\d.]+)\s*([kmg]?b)/i.exec(String(text || ''));
  return m ? parseFloat(m[1]) * UNITS[m[2].toLowerCase()] : 0;
}

function binaryBytes(binary) {
  let total = 0;
  for (const file of Object.values(binary)) {
    if (!file) continue;
    // In-memory binary mode: base64 payload is inline. Filesystem/S3 mode: only metadata.
    if (typeof file.data === 'string' && file.data.length > 0 && !file.id) {
      total += Math.floor((file.data.length * 3) / 4);
    } else {
      total += parseFileSize(file.fileSize);
    }
  }
  return total;
}

const rows = [];
for (const [node, runs] of Object.entries(runData)) {
  let items = 0;
  let jsonBytes = 0;
  let binBytes = 0;
  let ms = 0;
  for (const run of runs || []) {
    ms += run.executionTime || 0;
    for (const outputs of Object.values(run.data || {})) {
      for (const output of outputs || []) {
        for (const item of output || []) {
          items++;
          jsonBytes += JSON.stringify(item.json === undefined ? {} : item.json).length;
          if (item.binary) binBytes += binaryBytes(item.binary);
        }
      }
    }
  }
  rows.push({
    node,
    runs: (runs || []).length,
    items,
    jsonMB: +(jsonBytes / MB).toFixed(3),
    binaryMB: +(binBytes / MB).toFixed(3),
    totalMB: +((jsonBytes + binBytes) / MB).toFixed(3),
    executionMs: ms,
  });
}

rows.sort((a, b) => b.totalMB - a.totalMB);

// n8n keeps every node's output in memory until the execution ends, so the
// footprint is the SUM of all nodes, not the largest one. A JS object usually
// takes 2-4x its JSON size on the heap; manual runs also copy data for the editor.
const dataMB = rows.reduce((s, r) => s + r.totalMB, 0);
const jsonMB = rows.reduce((s, r) => s + r.jsonMB, 0);
const binMB = dataMB - jsonMB;
const estLowMB = jsonMB * 2 + binMB;
const estHighMB = jsonMB * 4 + binMB * 2;
const limitMB = Number(settings.planLimitMB) || 0;
const pct = limitMB ? Math.round((estHighMB / limitMB) * 100) : null;

let verdict = 'Set planLimitMB in Settings to get a verdict.';
if (limitMB) {
  if (pct >= 60) verdict = `HIGH RISK: up to ~${pct}% of your plan limit, and n8n itself also needs memory. Batch or split this workflow.`;
  else if (pct >= 30) verdict = `CAUTION: up to ~${pct}% of plan limit. Concurrent runs or bigger inputs could tip it over.`;
  else verdict = `OK: up to ~${pct}% of plan limit for this input size.`;
}

const summary = {
  node: '=== SUMMARY ===',
  executionId: exec.id,
  workflowId: exec.workflowId,
  status: exec.status,
  mode: exec.mode,
  nodes: rows.length,
  dataHeldMB: +dataMB.toFixed(2),
  estimatedHeapMB: `${estLowMB.toFixed(0)}-${estHighMB.toFixed(0)}`,
  planLimitMB: limitMB || null,
  verdict,
  topOffenders: rows.slice(0, 3).map((r) => `${r.node} (${r.totalMB} MB)`).join(', '),
};

return [summary, ...rows].map((json) => ({ json }));
